use strict;
use warnings;
use Test::More;
use Badge;

subtest benign_control => sub {
    is(Badge::render('ok'), '<span class="badge">ok</span>', 'renders a plain label');
};

subtest security_escapes_markup => sub {
    my $html = Badge::render('<script>alert(1)</script>');
    unlike($html, qr/<script>/, 'does not emit the label as markup');
};

done_testing();

